<script setup lang="ts">
import {ref,computed,onMounted} from 'vue';import {useRoute} from 'vue-router';import {api,date,errorText} from '../api';import {useAuth} from '../stores/auth';import PageHeading from '../components/PageHeading.vue';import StatusBadge from '../components/StatusBadge.vue';import Modal from '../components/Modal.vue';import {Upload,FileText,Plus,Download,ArrowRight} from 'lucide-vue-next';
const route=useRoute(),auth=useAuth(),docs=ref<any[]>([]),works=ref<any[]>([]),filter=ref('all'),error=ref(''),busy=ref(false),loading=ref(true),selected=ref<any>(null),file=ref<File|null>(null),comment=ref(''),decision=ref('accepted'),show=ref(false),reminder=ref<any>(null);const form=ref({work_item_id:Number(route.query.work_item_id)||'',title:'',instructions:'',due_on:'',required:true});const filtered=computed(()=>docs.value.filter(d=>filter.value==='all'||(filter.value==='review'?['received','reviewing'].includes(d.status):['pending','correction'].includes(d.status))));
async function load(){loading.value=true;try{docs.value=(await api.get('/documents',{params:{company_id:route.query.company_id,work_item_id:route.query.work_item_id}})).data;}catch(e){error.value=errorText(e);}finally{loading.value=false;}}
function open(d:any){selected.value=d;file.value=null;comment.value='';decision.value='accepted';error.value='';}
async function upload(){if(!file.value){error.value='Selecciona un archivo.';return}busy.value=true;try{const fd=new FormData();fd.append('file',file.value);await api.post(`/documents/${selected.value.id}/upload`,fd);selected.value=null;await load();}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
async function review(){busy.value=true;try{await api.patch(`/documents/${selected.value.id}`,{status:decision.value,comment:comment.value,version:selected.value.version,file_id:selected.value.files[0]?.id});selected.value=null;await load();}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
async function create(){busy.value=true;try{await api.post('/documents',{...form.value,due_on:form.value.due_on||null});show.value=false;await load();}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
onMounted(async()=>{await load();if(auth.staff)try{works.value=(await api.get('/works')).data.filter((w:any)=>!['approved','delivered','cancelled'].includes(w.status));}catch(e){error.value=errorText(e);}});
</script>
<template><PageHeading :title="auth.staff?'Antecedentes y documentos':'Mis pendientes'" :subtitle="auth.staff?'Recibe, revisa y conserva cada versión.':'Revisa las solicitudes de tu contador y adjunta tus archivos.'"><button v-if="auth.staff" class="button primary" @click="show=true"><Plus :size="16"/>Solicitar antecedente</button></PageHeading><div class="filter-tabs tabs-large"><button v-for="f in [{id:'all',label:'Todas las solicitudes'},{id:'review',label:'Para revisar'},{id:'pending',label:'Pendientes del cliente'}]" :key="f.id" :aria-pressed="filter===f.id" @click="filter=f.id">{{f.label}}</button></div><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="loading" class="empty">Cargando solicitudes…</p><section v-else class="panel"><div class="document-row" v-for="d in filtered" :key="d.id"><span class="file-icon"><FileText :size="22"/></span><div class="document-description"><strong>{{d.title}}</strong><small>{{d.company.name}} · {{d.work?.period}} · {{d.required?'Obligatorio':'Opcional'}}</small><p v-if="d.review_comment" class="review-comment">{{d.review_comment}}</p><small v-else>Fecha solicitada: {{date(d.due_on)}} · {{d.files.length}} archivo(s)</small></div><StatusBadge :status="d.status"/><div class="actions"><button class="button" @click="open(d)">{{auth.staff?'Revisar':'Ver solicitud'}} <ArrowRight :size="14"/></button><button v-if="auth.staff&&['pending','correction'].includes(d.status)" class="icon-button" aria-label="Preparar recordatorio" @click="reminder=d">Recordar</button></div></div><p v-if="!filtered.length" class="empty">No hay solicitudes en esta vista.</p></section><Modal v-if="selected" :title="selected.title" @close="selected=null"><p>{{selected.company.name}} · {{selected.work?.period}}</p><p class="instructions">{{selected.instructions||'Adjunta los antecedentes solicitados por tu contador.'}}</p><StatusBadge :status="selected.status"/><p v-if="selected.review_comment" class="review-comment">{{selected.review_comment}}</p><h3 class="section-label">Historial de archivos</h3><a v-for="(f,i) in selected.files" :key="f.id" :href="`/api/files/${f.id}`" class="file-download"><FileText :size="17"/><span>{{f.original_name}}<small>{{i===0?'Última versión':'Versión anterior'}} · {{date(f.created_at)}}</small></span><Download :size="16"/></a><p v-if="!selected.files.length" class="empty compact">Todavía no hay archivos.</p><form v-if="!['accepted','not_applicable'].includes(selected.status)" class="stack-form" @submit.prevent="upload"><label>Adjuntar archivo (máximo 10 MB)<input type="file" accept=".pdf,.jpg,.jpeg,.png,.xlsx,.csv,.txt" @change="file=($event.target as HTMLInputElement).files?.[0]||null" required></label><button class="button primary" :disabled="busy"><Upload :size="16"/>{{busy?'Procesando…':'Enviar para revisión'}}</button></form><form v-if="auth.staff" class="stack-form review-form" @submit.prevent="review"><h3>Decisión de revisión</h3><label>Resultado<select v-model="decision"><option value="accepted">Aceptar documento</option><option value="reviewing">Marcar en revisión</option><option value="correction">Solicitar corrección</option><option v-if="auth.reviewer" value="not_applicable">No aplica</option></select></label><label>Comentario<textarea v-model="comment" :required="['correction','not_applicable'].includes(decision)" maxlength="3000" placeholder="Explica el motivo de la corrección o decisión."></textarea></label><button class="button" :disabled="busy">Guardar revisión</button></form><p v-if="error" class="error" role="alert">{{error}}</p></Modal><Modal v-if="show" title="Solicitar antecedente" @close="show=false"><form @submit.prevent="create" class="stack-form"><label>Trabajo<select v-model="form.work_item_id" required><option value="" disabled>Selecciona un trabajo</option><option v-for="w in works" :key="w.id" :value="w.id">{{w.company.name}} · {{w.title}} · {{w.period}}</option></select></label><label>Antecedente solicitado<input v-model="form.title" required maxlength="180"></label><label>Instrucciones<textarea v-model="form.instructions" maxlength="3000"></textarea></label><label>Fecha solicitada<input type="date" v-model="form.due_on"></label><label class="checkbox"><input type="checkbox" v-model="form.required">Obligatorio para avanzar</label><p v-if="error" class="error">{{error}}</p><button class="button primary" :disabled="busy">Crear solicitud</button></form></Modal><Modal v-if="reminder" title="Borrador de recordatorio" @close="reminder=null"><p>Hola. Para continuar con el trabajo de {{reminder.work?.period}} de {{reminder.company.name}}, necesitamos: {{reminder.title}}. Puedes adjuntarlo en tu portal de ExpressConta.</p><div class="panel-note" style="margin-top:20px">Este borrador no se ha enviado. La integración de mensajería todavía no está configurada.</div></Modal></template>
